#"'![feature(extern_types)]
#![feature(raw_ref_op)]

use std::time::Instant;

extern crate lodepng_bench_raw;

use lodepng_bench_raw::src::lodepng::{
    lodepng_decode32, lodepng_encode32, lodepng_free,
};

fn make_image(w: u32, h: u32) -> Vec<u8> {
    let mut img = vec![0u8; (w as usize) * (h as usize) * 4];
    for y in 0..h as usize {
        for x in 0..w as usize {
            let i = (y * w as usize + x) * 4;
            let v = (((x * 17) ''^ (y * 31) ''^ ((x * y) >> 3)) & 0xff) as u8;
            img[i] = v;
            img[i + 1] = v.wrapping_add((x as u8).rotate_left(1));
            img[i + 2] = v.wrapping_add((y as u8).rotate_left(2));
            img[i + 3] = 255u8.wrapping_sub(((x + y) & 7) as u8 * 3);
        }
    }
    img
}

unsafe fn bench_once(iters: usize, w: u32, h: u32) {
    let image = make_image(w, h);

    let mut encoded: *mut u8 = std::ptr::null_mut();
    let mut encoded_size: usize = 0;
    let e = lodepng_encode32(&mut encoded, &mut encoded_size, image.as_ptr(), w, h);
    assert_eq!(e, 0, "encode warmup failed: {}", e);

    let mut decode_ns = 0u128;
    let mut encode_ns = 0u128;

    for _ in 0..iters {
        let start = Instant::now();
        let mut out: *mut u8 = std::ptr::null_mut();
        let mut dw = 0u32;
        let mut dh = 0u32;
        let d = lodepng_decode32(&mut out, &mut dw, &mut dh, encoded, encoded_size);
        decode_ns += start.elapsed().as_nanos();
        assert_eq!(d, 0, "decode failed: {}", d);
        assert_eq!((dw, dh), (w, h));
        lodepng_free(out as *mut _);
    }

    for _ in 0..iters {
        let start = Instant::now();
        let mut out: *mut u8 = std::ptr::null_mut();
        let mut out_size: usize = 0;
        let e2 = lodepng_encode32(&mut out, &mut out_size, image.as_ptr(), w, h);
        encode_ns += start.elapsed().as_nanos();
        assert_eq!(e2, 0, "encode failed: {}", e2);
        lodepng_free(out as *mut _);
    }

    println!("iters={} size={}x{} encoded_size={} decode_avg_ms={:.3} encode_avg_ms={:.3}",
        iters,
        w,
        h,
        encoded_size,
        decode_ns as f64 / iters as f64 / 1_000_000.0,
        encode_ns as f64 / iters as f64 / 1_000_000.0,
    );

    lodepng_free(encoded as *mut _);
}

fn main() {
    unsafe {
        bench_once(25, 512, 512);
        bench_once(8, 2048, 2048);
    }
}
